import java.util.*;

class Solution {
  public int countGoodNodes(int[][] edges) {
    int n = edges.length + 1;
    List<Integer>[] g = new ArrayList[n];
    for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(e[1]);
      g[e[1]].add(e[0]);
    }
    int[] parent = new int[n], order = new int[n];
    Arrays.fill(parent, -1);
    int size = 1;
    order[0] = 0;
    for (int i = 0; i < size; i++) {
      int u = order[i];
      for (int v : g[u])
        if (v != parent[u]) {
          parent[v] = u;
          order[size++] = v;
        }
    }
    int[] sub = new int[n];
    Arrays.fill(sub, 1);
    int result = 0;
    for (int i = n - 1; i >= 0; i--) {
      int u = order[i], childSize = -1;
      boolean good = true;
      for (int v : g[u])
        if (v != parent[u]) {
          sub[u] += sub[v];
          if (childSize < 0) childSize = sub[v];
          else if (childSize != sub[v]) good = false;
        }
      if (good) result++;
    }
    return result;
  }
}
